16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.util.*;
25	
26	/**
27	 * Simple JavaBean domain object representing an owner.
28	 *
29	 * @author Ken Krebs
30	 * @author Juergen Hoeller
31	 * @author Sam Brannen
32	 * @author Michael Isvy
33	 */
34	@Entity
35	@Table(name = "owners")
36	public class Owner extends Person {
37	    @Column(name = "address")
38	    @NotEmpty
39	    private String address;
40	
41	    @Column(name = "city")
42	    @NotEmpty
43	    private String city;
44	
45	    @Column(name = "telephone")
46	    @NotEmpty
47	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be E.164 form: '+' followed by 8 to 15 digits")
48	    private String telephone;
49	
50	    @Column(name = "email")
51	    private String email;
52	
53	    @Column(name = "registration_date", columnDefinition = "DATE")
54	    private java.time.LocalDate registrationDate;
55	
56	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
57	    private Set<Pet> pets;
58	
59	    public String getAddress() {
60	        return this.address;
61	    }
62	
63	    public void setAddress(String address) {
64	        this.address = address;
65	    }
66	
67	    public String getCity() {
68	        return this.city;
69	    }
70	
71	    public void setCity(String city) {
72	        this.city = city;
73	    }
74	
75	    public String getTelephone() {
76	        return this.telephone;
77	    }
78	
79	    public void setTelephone(String telephone) {
80	        this.telephone = telephone;
81	    }
82	
83	    public String getEmail() {
84	        return this.email;
85	    }
86	
87	    public void setEmail(String email) {
88	        this.email = email;
89	    }
90	
91	    public java.time.LocalDate getRegistrationDate() {
92	        return this.registrationDate;
93	    }
94	
95	    public void setRegistrationDate(java.time.LocalDate registrationDate) {
96	        this.registrationDate = registrationDate;
97	    }
98	
99	    protected Set<Pet> getPetsInternal() {
100	        if (this.pets == null) {
101	            this.pets = new HashSet<>();
102	        }
103	        return this.pets;
104	    }
105	
106	    protected void setPetsInternal(Set<Pet> pets) {
107	        this.pets = pets;
108	    }
109	
110	    public List<Pet> getPets() {
111	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
112	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
113	        return Collections.unmodifiableList(sortedPets);
114	    }
115	
116	    public void setPets(List<Pet> pets) {
117	        this.pets = new HashSet<>(pets);
118	    }
119	
120	    public void addPet(Pet pet) {
121	        getPetsInternal().add(pet);
122	        pet.setOwner(this);
123	    }
124	
125	    /**
126	     * Return the Pet with the given name, or null if none found for this Owner.
127	     *
128	     * @param name to test
129	     * @return true if pet name is already in use
130	     */
131	    public Pet getPet(String name) {
132	        return getPet(name, false);
133	    }
134	
135	    /**
136	     * Return the Pet with the given name, or null if none found for this Owner.
137	     *
138	     * @param name to test
139	     * @return true if pet name is already in use
140	     */
141	    public Pet getPet(String name, boolean ignoreNew) {
142	        name = name.toLowerCase();
143	        for (Pet pet : getPetsInternal()) {
144	            if (!ignoreNew || !pet.isNew()) {
145	                String compName = pet.getName();
146	                compName = compName.toLowerCase();
147	                if (compName.equals(name)) {
148	                    return pet;
149	                }
150	            }
151	        }
152	        return null;
153	    }
154	
155	    public Pet getPet(Integer petId) {
156	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
157	    }
158	
159	    @Override
160	    public String toString() {
161	        return new ToStringCreator(this)
162	
163	            .append("id", this.getId())
164	            .append("new", this.isNew())
165	            .append("lastName", this.getLastName())
166	            .append("firstName", this.getFirstName())
167	            .append("address", this.address)
168	            .append("city", this.city)
169	            .append("telephone", this.telephone)
170	            .toString();
171	    }
172	}
