1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import jakarta.validation.Valid;
7	import net.officefloor.plugin.variable.Out;
8	import org.springframework.samples.petclinic.mapper.OwnerMapper;
9	import org.springframework.samples.petclinic.model.Owner;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
12	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
13	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
14	import org.springframework.validation.annotation.Validated;
15	import org.springframework.web.bind.annotation.RequestBody;
16	
17	@Validated
18	public class BuildOwner {
19	
20	    /** Simple syntactic email check: non-space local part, '@', non-space domain with a dot. */
21	    private static final java.util.regex.Pattern EMAIL =
22	            java.util.regex.Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
23	
24	    public void service(@Valid @RequestBody OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built)
25	            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException {
26	        List<String> missing = new ArrayList<>();
27	        if (isBlank(request.getFirstName())) {
28	            missing.add("firstName");
29	        }
30	        if (isBlank(request.getLastName())) {
31	            missing.add("lastName");
32	        }
33	        if (isBlank(request.getAddress())) {
34	            missing.add("address");
35	        }
36	        if (isBlank(request.getCity())) {
37	            missing.add("city");
38	        }
39	        if (isBlank(request.getTelephone())) {
40	            missing.add("telephone");
41	        }
42	        if (!missing.isEmpty()) {
43	            throw new MissingOwnerFieldsException(missing);
44	        }
45	        request.setTelephone(TelephoneNormalizer.normalize(request.getTelephone()));
46	        request.setEmail(normalizeEmail(request.getEmail()));
47	        Owner owner = ownerMapper.toOwner(request);
48	        if (owner.getRegistrationDate() == null) {
49	            owner.setRegistrationDate(java.time.LocalDate.now());
50	        }
51	        built.set(owner);
52	    }
53	
54	    /** When present, require a syntactically valid address and store it lower-cased; else reject with 400. */
55	    private static String normalizeEmail(String email) throws InvalidEmailException {
56	        if (email == null || email.isBlank()) {
57	            return null;
58	        }
59	        String trimmed = email.trim();
60	        if (!EMAIL.matcher(trimmed).matches()) {
61	            throw new InvalidEmailException(email);
62	        }
63	        return trimmed.toLowerCase(java.util.Locale.ROOT);
64	    }
65	
66	    private static boolean isBlank(String value) {
67	        return value == null || value.isBlank();
68	    }
69	}
