2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
7	
8	/**
9	 * Rejects a create-owner request whose normalized telephone is already used by any other
10	 * owner, with a 409 Conflict. Runs after {@link BuildOwner} has normalized the telephone.
11	 */
12	public class CheckOwnerTelephoneUnique {
13	
14	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
15	            throws DuplicateTelephoneException {
16	        String telephone = TelephoneNormalizer.comparisonKey(owner.getTelephone());
17	        for (Owner existing : ownerRepository.findAll()) {
18	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
19	                continue; // same record (e.g. re-save), not a conflict
20	            }
21	            if (telephone.equals(TelephoneNormalizer.comparisonKey(existing.getTelephone()))) {
22	                throw new DuplicateTelephoneException(owner.getTelephone());
23	            }
24	        }
25	    }
26	}
